const primeFib = (n) => {
  if (n < 1) throw new Error('n must be >= 1');
  const isPrime = (num) => {
    if (num < 2) return false;
    if (num === 2) return true;
    if (num % 2 === 0) return false;
    const sqrt = Math.floor(Math.sqrt(num));
    for (let i = 3; i <= sqrt; i += 2) {
      if (num % i === 0) return false;
    }
    return true;
  };
  let count = 0;
  let a = 0, b = 1;
  while (true) {
    const fib = b;
    if (isPrime(fib)) {
      count++;
      if (count === n) return fib;
    }
    const next = a + b;
    a = b;
    b = next;
  }
};

